function FIRE_AND_CHECK(G, D, f):
    for each vertex v in V(G):
        lap[v] <- 0
        for each w adjacent to v:
            lap[v] <- lap[v] + (f[v] - f[w])
    for each vertex v:
        D'[v] <- D[v] + lap[v]
    return (D', deg(D') == deg(D))   # always True by Theorem 3.2

